const STATE_ALIASES = {
  "Odisha": ["orissa"],
  "Uttarakhand": ["uttaranchal"],
  "Tamil Nadu": ["tamilnadu"],
  "Puducherry": ["pondicherry"],
  "Delhi": ["new delhi", "nct of delhi", "ncr"],
  "Jammu & Kashmir and Ladakh": ["jammu and kashmir", "jammu kashmir", "kashmir", "ladakh", "jk", "j k"],
  "Dadra & Nagar Haveli and Daman & Diu": ["dnh", "dadra and nagar haveli", "daman and diu", "dnhdd"],
  "Andaman & Nicobar Islands": ["andaman", "andaman and nicobar", "andaman nicobar"],
};

function normalize(s) {
  return s
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/['’`.]/g, "")
    .replace(/[^a-z\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// One transposition or typo is forgiven on longer names — Indian city names
// are long, and the point is recall, not orthography.
function within1(a, b) {
  if (a === b) return true;
  const la = a.length, lb = b.length;
  if (Math.abs(la - lb) > 1) return false;
  if (la === lb) {
    const diff = [];
    for (let i = 0; i < la; i++) if (a[i] !== b[i]) diff.push(i);
    if (diff.length === 1) return true; // one substitution
    // one adjacent transposition: Bhubaneshwar, Vishakapatnam, Gawuhati
    return (
      diff.length === 2 &&
      diff[1] === diff[0] + 1 &&
      a[diff[0]] === b[diff[1]] &&
      a[diff[1]] === b[diff[0]]
    );
  }
  // one insertion or deletion
  const s = la < lb ? a : b, l = la < lb ? b : a;
  let i = 0, j = 0, skipped = false;
  while (i < s.length && j < l.length) {
    if (s[i] === l[j]) { i++; j++; continue; }
    if (skipped) return false;
    skipped = true;
    j++;
  }
  return true;
}

// ---------- projection (Mercator, computed once) ----------

function mercRaw(lon, lat) {
  const phi = (Math.max(-85, Math.min(85, lat)) * Math.PI) / 180;
  return [(lon * Math.PI) / 180, Math.log(Math.tan(Math.PI / 4 + phi / 2))];
}

const W = 800;
const H = 800;
const PAD = 24;

const FIT = (() => {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  const scan = (ring) => {
    for (const [lon, lat] of ring) {
      const [x, y] = mercRaw(lon, lat);
      if (x < x0) x0 = x;
      if (x > x1) x1 = x;
      if (y < y0) y0 = y;
      if (y > y1) y1 = y;
    }
  };
  for (const c of STATES_RAW) for (const poly of c.geometry.coordinates) for (const r of poly) scan(r);
  const k = Math.min((W - 2 * PAD) / (x1 - x0), (H - 2 * PAD) / (y1 - y0));
  return { k, tx: (W - k * (x0 + x1)) / 2, ty: (H + k * (y0 + y1)) / 2 };
})();

function project(lon, lat) {
  const [x, y] = mercRaw(lon, lat);
  return [FIT.k * x + FIT.tx, FIT.ty - FIT.k * y];
}

function invert(px, py) {
  const x = (px - FIT.tx) / FIT.k;
  const y = (FIT.ty - py) / FIT.k;
  return [(x * 180) / Math.PI, ((2 * Math.atan(Math.exp(y)) - Math.PI / 2) * 180) / Math.PI];
}

function ringToPath(ring) {
  let d = "";
  for (let i = 0; i < ring.length; i++) {
    const [x, y] = project(ring[i][0], ring[i][1]);
    d += (i ? "L" : "M") + x.toFixed(1) + "," + y.toFixed(1);
  }
  return d + "Z";
}

function polysToPath(polys) {
  let d = "";
  for (const poly of polys) for (const ring of poly) d += ringToPath(ring);
  return d;
}

const STATE_PATHS = STATES_RAW.map((c) => polysToPath(c.geometry.coordinates));
const BORDER_PATH = STATE_PATHS.join("");
// Looked up by id when a wrong state-mode guess needs to highlight the
// actual target shape instead of a point marker.
const STATE_PATH_BY_ID = Object.fromEntries(STATES_RAW.map((s, i) => [s.id, STATE_PATHS[i]]));
// Same recipe as STATE_PATHS, one path per elevation band, low to high —
// painted in that order so each higher band draws over the one below it.
const ELEV_PATHS = ELEV_BANDS.map((b) => ({ d: polysToPath(b.geometry.coordinates), color: b.color }));

function kmBetween(lon1, lat1, lon2, lat2) {
  const R = 6371, t = Math.PI / 180;
  const dLat = (lat2 - lat1) * t, dLon = (lon2 - lon1) * t;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * t) * Math.cos(lat2 * t) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

const CITIES = CITIES_RAW.map((c) => {
  const [x, y] = project(c.lon, c.lat);
  const extra = ALIASES[c.n] || [];
  return {
    ...c,
    id: normalize(c.n).replace(/\s/g, "-"),
    x,
    y,
    accepted: [normalize(c.n), ...extra.map(normalize)],
  };
});

// The state/UT pool: same recipe as CITIES, but there's only ever one of it —
// no admin/econ split to filter by, so no POOLS object needed here.
const STATE_POOL = STATE_ITEMS_RAW.map((c) => {
  const [x, y] = project(c.lon, c.lat);
  const extra = STATE_ALIASES[c.n] || [];
  return {
    ...c,
    x,
    y,
    accepted: [normalize(c.n), ...extra.map(normalize)],
  };
});

// Shapes too small to reliably hit at default zoom — union territories and a
// few small states, picked by land area. Only the states game needs this: a
// city is a point with a generous radius around it, but a state has to be
// hit inside its own outline, and some outlines are a few pixels wide.
const STATE_SMALL = new Set(["LD", "CH", "PY", "DH", "DL", "GA", "AN", "SK", "TR"]);

// Three ways to narrow the field. "All" is every seat and every commercial
// centre. "Capitals" is one city per state/UT — the seat of government,
// which is the answer to "what is the capital of X". "Commercial" is one
// city per state/UT — where the money actually is, which is often the same
// city and sometimes emphatically isn't.
const SCOPES = {
  all: { label: "All", filter: () => true },
  admin: { label: "Capitals", filter: (c) => c.admin },
  econ: { label: "Commercial", filter: (c) => c.econ },
};

// A second, independent way to narrow the field: by size. "pop" is always a
// string like "~2.7M" or "~30K" — fine for the answer card, not sortable as
// written, so this turns it back into a number.
function parsePop(pop) {
  const m = /^~?([\d.]+)([KM])$/.exec(pop);
  if (!m) return 0;
  return parseFloat(m[1]) * (m[2] === "M" ? 1e6 : 1e3);
}

const POP_TIERS = {
  third: { label: "Top ⅓", frac: 1 / 3 },
  twoThirds: { label: "Top ⅔", frac: 2 / 3 },
  all: { label: "All sizes", frac: 1 },
};

// Ranks whatever pool is already in play (scope narrows by role, this narrows
// by size) and keeps the biggest slice of it — the cities someone drilling
// for recall is likeliest to actually need, with the long tail of small
// state capitals and commercial towns left for when "All" is selected.
function topByPopulation(pool, frac) {
  if (frac >= 1) return pool;
  const ranked = [...pool].sort((a, b) => parsePop(b.pop) - parsePop(a.pop));
  return ranked.slice(0, Math.max(1, Math.ceil(ranked.length * frac)));
}

const POOLS = Object.fromEntries(
  Object.entries(SCOPES).map(([k, s]) => [k, CITIES.filter(s.filter)])
);

// How close counts, in kilometres — the only thing that decides a tap.
//
// A single fixed number can't serve the whole country: 150 km is roomy around
// Delhi and stingy out in Ladakh, where the nearest other drill city is
// hundreds of kilometres away. So an isolated city earns a wider allowance,
// scaled off the distance to its nearest neighbour in the pool. The floor
// means no city is ever tighter than 150 km, however crowded its corner of
// the map — landing near a neighbour costs you nothing, since the neighbour
// isn't consulted.
//
// Everything here is geographic. Zoom affects only how accurately you can
// place your finger, never what counts as close enough, so zooming in to look
// carefully can help you and can never cost you.
const GEO_TOL_MIN_KM = 150;
const GEO_TOL_MAX_KM = 500;

function toleranceFor(pool, city) {
  let nearestOther = Infinity;
  for (const o of pool) {
    if (o === city) continue;
    const d = kmBetween(city.lon, city.lat, o.lon, o.lat);
    if (d < nearestOther) nearestOther = d;
  }
  return Math.min(GEO_TOL_MAX_KM, Math.max(GEO_TOL_MIN_KM, nearestOther / 2));
}

// Per-city tap allowance, in km, for each pool. Depends on the pool because
// narrowing the scope moves a city's nearest neighbour further away.
const TOLERANCES = Object.fromEntries(
  Object.entries(POOLS).map(([k, pool]) => [
    k,
    Object.fromEntries(pool.map((c) => [c.id, toleranceFor(pool, c)])),
  ])
);

function matches(city, text) {
  const t = normalize(text);
  if (!t) return false;
  return city.accepted.some((a) => a === t || (a.length >= 6 && within1(a, t)));
}

function shuffled(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

// One answered state, filled and outlined in its verdict colour. Small states
// and union territories get a ring around them as well: Puducherry or
// Chandigarh shaded green is a few invisible pixels at default zoom, so
// without the ring the correct answer may as well not be drawn at all.
function StateHighlight({ id, color, k }) {
  const d = STATE_PATH_BY_ID[id];
  if (!d) return null;
  const item = STATE_POOL.find((s) => s.id === id);
  return (
    <g>
      <path
        d={d}
        fillRule="evenodd"
        fill={color}
        fillOpacity={0.45}
        stroke={color}
        strokeWidth={2.2 / k}
        strokeLinejoin="round"
        opacity={0.9}
      />
      {STATE_SMALL.has(id) && item && (
        <circle
          cx={item.x}
          cy={item.y}
          r={15 / k}
          fill="none"
          stroke={color}
          strokeWidth={2 / k}
          opacity={0.95}
        />
      )}
    </g>
  );
}

export default function IndianAtlasDrill() {
  const [domain, setDomain] = useState("cities");
  const [input, setInput] = useState("type");
  const [session, setSession] = useState("practice");
  const [scope, setScope] = useState("all");
  const [popTier, setPopTier] = useState("all");
  // Borders are on by default here: a city drill without them is guesswork,
  // since half of what you're recalling is which state the dot sits in.
  const [borders, setBorders] = useState(true);
  const [elevation, setElevation] = useState(true);
  const [hints, setHints] = useState(false);
  const pool =
    domain === "cities" ? topByPopulation(POOLS[scope], POP_TIERS[popTier].frac) : STATE_POOL;

  return (
    <div className="icq-page" style={S.page}>
      <style>{`
        @keyframes icq-pop { from { transform: scale(0.9); opacity: 0 } to { transform: scale(1); opacity: 1 } }
        @keyframes icq-shake { 0%,100% { transform: translateX(0) } 25% { transform: translateX(-5px) } 75% { transform: translateX(5px) } }
        @keyframes icq-ping { 0% { transform: scale(.55); opacity: .95 } 100% { transform: scale(1.9); opacity: 0 } }
        .icq-ping { transform-box: fill-box; transform-origin: center; animation: icq-ping 1.7s ease-out infinite; }
        .icq-btn { transition: background-color .15s, border-color .15s, transform .1s; cursor: pointer; }
        .icq-btn:active { transform: scale(.97); }
        .icq-btn:focus-visible, .icq-input:focus-visible { outline: 2px solid #e3a542; outline-offset: 2px; }
        .icq-input:focus { outline: none; border-color: #e3a542 !important; }
        .icq-map svg:active { cursor: grabbing; }
        @media (prefers-reduced-motion: reduce) { * { animation: none !important; } }

        .icq-page { padding: 20px 14px 40px; }
        .icq-panel { max-width: 460px; padding: 14px; border-radius: 16px; }
        .icq-map { border-radius: 12px; }
        .icq-layout { display: flex; flex-direction: column; gap: 14px; }
        .icq-side { display: flex; flex-direction: column; gap: 10px; min-width: 0; }

        @media (max-width: 560px) {
          .icq-page { padding: 14px 0 28px; }
          .icq-panel {
            max-width: 100%;
            padding: 12px 12px 16px;
            border-radius: 0;
            border-left: none;
            border-right: none;
          }
          .icq-map {
            margin-left: -12px;
            margin-right: -12px;
            width: calc(100% + 24px);
            border-radius: 0;
            border-left: none;
            border-right: none;
          }
        }

        /* Laptop/desktop: map and prompt sit side by side instead of stacked,
           since there's finally room to see both the question and the answer
           at once instead of scrolling between them. */
        @media (min-width: 900px) {
          .icq-panel { max-width: 980px; }
          .icq-layout { flex-direction: row; align-items: flex-start; gap: 22px; }
          .icq-map { flex: 0 0 560px; width: 560px; }
          .icq-side { flex: 1 1 320px; min-width: 300px; padding-top: 2px; }
        }
      `}</style>

      <div style={S.header}>
        <div style={S.eyebrow}>ATLAS DRILL</div>
        <h1 style={S.title}>Indian {domain === "states" ? "States" : "Cities"} · {pool.length}</h1>
        <div style={S.sub}>
          {domain === "states"
            ? "every state and union territory — one shape each, no political or commercial split"
            : SCOPE_BLURB[scope]}
          {domain === "cities" && popTier !== "all" && ` — ${POP_TIERS[popTier].label.toLowerCase()} by population`}
        </div>
      </div>

      <div style={S.modeRow}>
        <ModeButton label="States" active={domain === "states"} onClick={() => setDomain("states")} />
        <ModeButton label="Cities" active={domain === "cities"} onClick={() => setDomain("cities")} />
      </div>

      <div style={S.modeRow}>
        <ModeButton label="Name it" active={input === "type"} onClick={() => setInput("type")} />
        <ModeButton label="Find it" active={input === "tap"} onClick={() => setInput("tap")} />
      </div>

      <div className="icq-panel" style={S.panel}>
        {domain === "cities" && (
          <div style={S.segRow}>
            {Object.entries(SCOPES).map(([k, s]) => (
              <SegButton key={k} label={s.label} active={scope === k} onClick={() => setScope(k)} />
            ))}
          </div>
        )}

        {domain === "cities" && (
          <div style={S.segRow}>
            {Object.entries(POP_TIERS).map(([k, t]) => (
              <SegButton key={k} label={t.label} active={popTier === k} onClick={() => setPopTier(k)} />
            ))}
          </div>
        )}

        <div style={S.segRow}>
          <SegButton label="Practice" active={session === "practice"} onClick={() => setSession("practice")} />
          <SegButton label={JOURNEY_LABEL[domain]} active={session === "journey"} onClick={() => setSession("journey")} />
        </div>

        <Quiz
          key={domain + session + scope + popTier}
          domain={domain}
          pool={pool}
          smallShapes={STATE_SMALL}
          tolerances={domain === "cities" ? TOLERANCES[scope] : null}
          input={input}
          session={session}
          borders={borders}
          elevation={elevation}
          hints={hints}
        />

        <div style={S.toggleRow}>
          <Toggle on={borders} onClick={() => setBorders((b) => !b)} label={"Borders " + (borders ? "on" : "off")} />
          <Toggle on={elevation} onClick={() => setElevation((e) => !e)} label={"Elevation " + (elevation ? "on" : "off")} />
          <Toggle on={hints} onClick={() => setHints((h) => !h)} label={"Hints " + (hints ? "on" : "off")} />
        </div>
      </div>
    </div>
  );
}

const SCOPE_BLURB = {
  all: "every state and union-territory capital, plus the commercial hub where it differs",
  admin: "one per state or union territory — the seat of government",
  econ: "one per state or union territory — where the money is",
};

function Toggle({ on, onClick, label }) {
  return (
    <button
      className="icq-btn"
      onClick={onClick}
      aria-pressed={on}
      style={{
        ...S.toggleBtn,
        color: on ? "#c9d2e4" : "#8b93a7",
        borderColor: on ? "#5a6579" : "#2a3241",
      }}
    >
      <span style={{ ...S.toggleDot, background: on ? "#7c88a3" : "transparent" }} />
      {label}
    </button>
  );
}

function ModeButton({ label, active, onClick }) {
  return (
    <button
      className="icq-btn"
      onClick={onClick}
      style={{
        ...S.modeBtn,
        backgroundColor: active ? "#e3a542" : "transparent",
        color: active ? "#12161f" : "#8b93a7",
        borderColor: active ? "#e3a542" : "#2a3241",
      }}
    >
      {label}
    </button>
  );
}

function Borders({ on, k = 1 }) {
  if (!on) return null;
  return (
    <path
      d={BORDER_PATH}
      fill="none"
      stroke="#7c88a3"
      strokeWidth={0.9 / k}
      strokeLinejoin="round"
      opacity={0.75}
      pointerEvents="none"
    />
  );
}

function BaseMap({ dim, k = 1, elevation }) {
  const seam = { fill: dim, stroke: dim, strokeWidth: 1 / k, strokeLinejoin: "round" };
  return (
    <>
      <rect x={-2000} y={-2000} width={6000} height={6000} fill="#0c1219" />
      {STATE_PATHS.map((d, i) => (
        <path key={i} d={d} fillRule="evenodd" {...seam} />
      ))}
      {elevation &&
        ELEV_PATHS.map((b, i) => (
          <path
            key={i}
            d={b.d}
            fillRule="evenodd"
            fill={b.color}
            stroke={b.color}
            strokeWidth={0.6 / k}
            strokeLinejoin="round"
            opacity={0.92}
          />
        ))}
    </>
  );
}

function useMapGestures(onTapLonLat) {
  const [view, setView] = useState({ k: 1, tx: 0, ty: 0 });
  const svgRef = useRef(null);
  const gRef = useRef(null);
  const gesture = useRef(null);
  const lastTouchTap = useRef(0);

  const toLocal = useCallback((clientX, clientY, el) => {
    if (!svgRef.current || !el) return null;
    const pt = svgRef.current.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    const ctm = el.getScreenCTM();
    return ctm ? pt.matrixTransform(ctm.inverse()) : null;
  }, []);

  const handleTap = useCallback(
    (clientX, clientY) => {
      const p = toLocal(clientX, clientY, gRef.current);
      if (!p) return;
      const [lon, lat] = invert(p.x, p.y);
      onTapLonLat(lon, lat, { x: p.x, y: p.y }, view.k);
    },
    [toLocal, onTapLonLat, view.k]
  );

  useEffect(() => {
    const el = svgRef.current;
    if (!el) return;
    const mid = (a, b) => ({ x: (a.clientX + b.clientX) / 2, y: (a.clientY + b.clientY) / 2 });

    const startPinch = (t1, t2) => {
      const m = mid(t1, t2);
      gesture.current = {
        mode: "pinch",
        anchor: toLocal(m.x, m.y, gRef.current),
        startDist: Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY),
        startK: view.k,
      };
    };

    const onStart = (e) => {
      if (e.touches.length >= 2) startPinch(e.touches[0], e.touches[1]);
      else
        gesture.current = {
          mode: "tap",
          x: e.touches[0].clientX,
          y: e.touches[0].clientY,
          moved: false,
          lastLocal: toLocal(e.touches[0].clientX, e.touches[0].clientY, svgRef.current),
        };
    };

    const onMove = (e) => {
      const g = gesture.current;
      if (!g) return;
      if (e.touches.length >= 2) {
        if (g.mode !== "pinch") return startPinch(e.touches[0], e.touches[1]);
        e.preventDefault();
        const [t1, t2] = [e.touches[0], e.touches[1]];
        const d = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
        const k = clamp(g.startK * (d / g.startDist), 1, 16);
        const m = mid(t1, t2);
        const p = toLocal(m.x, m.y, svgRef.current);
        if (p && g.anchor) setView({ k, tx: p.x - k * g.anchor.x, ty: p.y - k * g.anchor.y });
      } else if (g.mode === "tap") {
        const touch = e.touches[0];
        if (Math.hypot(touch.clientX - g.x, touch.clientY - g.y) > 10) g.moved = true;
        // Once it's a drag rather than a tap, follow the finger: whatever map
        // point was under it a moment ago stays under it now.
        if (g.moved) {
          e.preventDefault();
          const cur = toLocal(touch.clientX, touch.clientY, svgRef.current);
          if (cur && g.lastLocal) {
            const dx = cur.x - g.lastLocal.x, dy = cur.y - g.lastLocal.y;
            setView((v) => ({ ...v, tx: v.tx + dx, ty: v.ty + dy }));
          }
          g.lastLocal = cur;
        }
      }
    };

    const onEnd = (e) => {
      const g = gesture.current;
      if (g && g.mode === "tap" && !g.moved) {
        e.preventDefault();
        lastTouchTap.current = Date.now();
        handleTap(g.x, g.y);
      }
      if (e.touches.length === 0) gesture.current = null;
    };

    el.addEventListener("touchstart", onStart, { passive: false });
    el.addEventListener("touchmove", onMove, { passive: false });
    el.addEventListener("touchend", onEnd, { passive: false });
    el.addEventListener("touchcancel", onEnd, { passive: false });
    return () => {
      el.removeEventListener("touchstart", onStart);
      el.removeEventListener("touchmove", onMove);
      el.removeEventListener("touchend", onEnd);
      el.removeEventListener("touchcancel", onEnd);
    };
  }, [toLocal, handleTap, view.k]);

  // Mouse equivalent of the touch drag above: click-and-drag pans, a plain
  // click still taps. Tracked on window rather than the svg so the drag
  // keeps following the cursor even if it leaves the map mid-gesture.
  const mouseDrag = useRef(null);
  const wasDragged = useRef(false);

  useEffect(() => {
    const el = svgRef.current;
    if (!el) return;

    const onDown = (e) => {
      if (e.button !== 0) return;
      wasDragged.current = false;
      mouseDrag.current = {
        x: e.clientX,
        y: e.clientY,
        moved: false,
        lastLocal: toLocal(e.clientX, e.clientY, svgRef.current),
      };
    };

    const onMove = (e) => {
      const g = mouseDrag.current;
      if (!g) return;
      if (!g.moved && Math.hypot(e.clientX - g.x, e.clientY - g.y) > 4) {
        g.moved = true;
        wasDragged.current = true;
      }
      if (g.moved) {
        const cur = toLocal(e.clientX, e.clientY, svgRef.current);
        if (cur && g.lastLocal) {
          const dx = cur.x - g.lastLocal.x, dy = cur.y - g.lastLocal.y;
          setView((v) => ({ ...v, tx: v.tx + dx, ty: v.ty + dy }));
        }
        g.lastLocal = cur;
      }
    };

    const onUp = () => {
      mouseDrag.current = null;
    };

    el.addEventListener("mousedown", onDown);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    return () => {
      el.removeEventListener("mousedown", onDown);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
  }, [toLocal]);

  const onClick = (e) => {
    if (wasDragged.current) {
      wasDragged.current = false;
      return;
    }
    if (Date.now() - lastTouchTap.current < 600) return;
    handleTap(e.clientX, e.clientY);
  };

  const onWheel = (e) => {
    e.preventDefault();
    const k = clamp(view.k * (e.deltaY < 0 ? 1.15 : 1 / 1.15), 1, 16);
    const p = toLocal(e.clientX, e.clientY, svgRef.current);
    const a = toLocal(e.clientX, e.clientY, gRef.current);
    if (p && a) setView({ k, tx: p.x - k * a.x, ty: p.y - k * a.y });
  };

  // Centre the view on a point in map units at a given zoom.
  const focus = (x, y, k) => setView({ k, tx: W / 2 - k * x, ty: H / 2 - k * y });
  const reset = () => setView({ k: 1, tx: 0, ty: 0 });

  return { view, reset, focus, svgRef, gRef, onClick, onWheel };
}

function TapMap({ gestures, children, label }) {
  const { view, reset, svgRef, gRef, onClick, onWheel } = gestures;
  return (
    <div className="icq-map" style={S.mapWrap}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${W} ${H}`}
        style={{ ...S.svg, touchAction: "none" }}
        onClick={onClick}
        onWheel={onWheel}
        role="img"
        aria-label={label}
      >
        <rect x={0} y={0} width={W} height={H} fill="#0c1219" />
        <g ref={gRef} transform={`translate(${view.tx},${view.ty}) scale(${view.k})`}>
          {children(view.k)}
        </g>
      </svg>
      <Compass />
      {(view.k > 1.01 || Math.abs(view.tx) > 0.5 || Math.abs(view.ty) > 0.5) && (
        <button className="icq-btn" style={S.reset} onClick={reset}>
          Reset view
        </button>
      )}
    </div>
  );
}

// A tap is right if it landed inside the target's allowance, full stop.
//
// There used to be a second condition — the target also had to be the closest
// city in the pool to your finger — meant to stop a lazy jab between two
// neighbours from counting. In practice it silently overrode the stated
// allowance: Delhi and Gurugram sit 25 km apart, so the real margin there was
// 12 km, not the advertised 150, and it quietly punished coastal cities whose
// allowance is half ocean. Distance to the target is the whole rule now, so
// the number the tolerance promises is the number you actually get.
function resolveTap(tol, lon, lat, target) {
  const km = kmBetween(lon, lat, target.lon, target.lat);
  return { correct: km <= tol, km };
}

// A tap in the states game is right if it lands inside the target's own
// outline — a shape, not a point, so "nearest dot within some radius"
// doesn't apply the way it does for cities.
function pointInRing(lon, lat, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0], yi = ring[i][1];
    const xj = ring[j][0], yj = ring[j][1];
    const crosses = yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi;
    if (crosses) inside = !inside;
  }
  return inside;
}

function pointInState(lon, lat, state) {
  for (const poly of state.geometry.coordinates) {
    if (pointInRing(lon, lat, poly[0])) return true;
  }
  return false;
}

// Each state was simplified on its own, so two shapes that share a real
// border can leave a hairline gap between their simplified outlines. A tap
// that lands in one of those slivers hits no shape at all — fall back to
// whichever state's outline is physically closest to the tap.
function nearestStateByBoundary(lon, lat) {
  let best = null, bestD = Infinity;
  for (const s of STATES_RAW) {
    for (const poly of s.geometry.coordinates) {
      for (const [x, y] of poly[0]) {
        const d = kmBetween(lon, lat, x, y);
        if (d < bestD) { bestD = d; best = s; }
      }
    }
  }
  return best;
}

function resolveStateTap(lon, lat, target) {
  const hit = STATES_RAW.find((s) => pointInState(lon, lat, s)) || nearestStateByBoundary(lon, lat);
  // The state you actually landed on comes back too, so a wrong guess can
  // show what you picked as well as what the answer was.
  return { correct: !!hit && hit.id === target.id, guessId: hit ? hit.id : null };
}

// ---------- the journey ----------
//
// Same road-trip framework for both games — one end of India to the other,
// roughly 3,800 km along the old NH44 corridor — but the waypoints are named
// in whichever unit you're actually drilling, so a state-mode run doesn't
// scroll through a list of cities.
const TOTAL_KM = 3800;

const CITY_LEGS = [
  { at: 0.0, name: "Srinagar" },
  { at: 0.09, name: "Jammu" },
  { at: 0.2, name: "Delhi" },
  { at: 0.3, name: "Jaipur" },
  { at: 0.4, name: "Bhopal" },
  { at: 0.5, name: "Nagpur" },
  { at: 0.62, name: "Hyderabad" },
  { at: 0.73, name: "Bengaluru" },
  { at: 0.85, name: "Madurai" },
  { at: 0.94, name: "Nagercoil" },
  { at: 1.0, name: "Kanyakumari" },
];

const STATE_LEGS = [
  { at: 0.0, name: "Jammu & Kashmir" },
  { at: 0.09, name: "Himachal Pradesh" },
  { at: 0.2, name: "Haryana" },
  { at: 0.3, name: "Rajasthan" },
  { at: 0.4, name: "Madhya Pradesh" },
  { at: 0.5, name: "Maharashtra" },
  { at: 0.62, name: "Telangana" },
  { at: 0.73, name: "Karnataka" },
  { at: 0.85, name: "Kerala" },
  { at: 0.94, name: "Tamil Nadu" },
  { at: 1.0, name: "Tamil Nadu" },
];

const JOURNEY_LABEL = {
  cities: `${CITY_LEGS[0].name} to ${CITY_LEGS[CITY_LEGS.length - 1].name}`,
  states: `${STATE_LEGS[0].name} to ${STATE_LEGS[STATE_LEGS.length - 1].name}`,
};

function legFor(frac, legs) {
  let l = legs[0];
  for (const leg of legs) if (frac >= leg.at) l = leg;
  return l.name;
}

// ---------- one quiz, two ways to answer, two ways to play ----------

function Quiz({ pool, smallShapes, tolerances, input, session, borders, elevation, hints, domain }) {
  const journey = session === "journey";
  const typing = input === "type";

  const [queue, setQueue] = useState(() => shuffled(pool.map((c) => c.id)));
  const [solved, setSolved] = useState(() => new Set());
  const [score, setScore] = useState({ correct: 0, total: 0 });
  // The last guess, right or wrong, stays here until the next one overwrites
  // it — the side panel reads straight off this instead of a timed flash, so
  // it survives exactly as long as it should: until you answer again.
  const [lastAnswer, setLastAnswer] = useState(null);
  const [typed, setTyped] = useState("");
  const inputRef = useRef(null);
  const answerSeq = useRef(0);

  const targetId = queue[0];
  const target = targetId ? pool.find((c) => c.id === targetId) : null;
  const arrived = journey && !target;

  useEffect(() => {
    if (typing && inputRef.current) inputRef.current.focus();
  }, [typing, targetId]);

  const advanceQueue = useCallback(
    (wasCorrect) => {
      setTyped("");
      setQueue((q) => {
        if (journey) return wasCorrect ? q.slice(1) : [...q.slice(1), q[0]];
        return q.length <= 1 ? shuffled(pool.map((c) => c.id)) : q.slice(1);
      });
    },
    [journey, pool]
  );

  // Score it, snapshot everything the side panel and the map reveal need
  // about the city just asked, then move straight on — no waiting for a
  // Next click, right or wrong.
  const recordAnswer = useCallback(
    (correct, extra) => {
      if (!target) return;
      setScore((s) => ({ correct: s.correct + (correct ? 1 : 0), total: s.total + 1 }));
      if (correct && journey) setSolved((prev) => new Set(prev).add(target.id));
      answerSeq.current += 1;
      setLastAnswer({
        key: answerSeq.current,
        id: target.id,
        n: target.n,
        country: target.country,
        capital: target.capital,
        role: target.role,
        b: target.b,
        pop: target.pop,
        tx: target.x,
        ty: target.y,
        correct,
        domain,
        ...extra,
      });
      advanceQueue(correct);
    },
    [target, journey, advanceQueue, domain]
  );

  const onTap = useCallback(
    (lon, lat, at) => {
      if (typing || !target) return;
      if (domain === "states") {
        const r = resolveStateTap(lon, lat, target);
        recordAnswer(r.correct, { atX: at.x, atY: at.y, guessId: r.guessId });
      } else {
        const r = resolveTap(tolerances[target.id], lon, lat, target);
        recordAnswer(r.correct, { atX: at.x, atY: at.y, km: r.km });
      }
    },
    [typing, target, tolerances, domain, recordAnswer]
  );

  const gestures = useMapGestures(onTap);

  const submitTyped = () => {
    if (!target || !typed.trim()) return;
    recordAnswer(matches(target, typed), { guessText: typed.trim() });
  };

  const restart = () => {
    setQueue(shuffled(pool.map((c) => c.id)));
    setSolved(new Set());
    setScore({ correct: 0, total: 0 });
    setLastAnswer(null);
    setTyped("");
    gestures.reset();
  };

  const count = solved.size;
  const frac = count / pool.length;
  const TARGET_FILL = "#f3e9d8";

  const noun = domain === "states" ? "state or territory" : "city";
  const legs = domain === "states" ? STATE_LEGS : CITY_LEGS;
  const journeyStart = legs[0].name;
  const journeyEnd = legs[legs.length - 1].name;

  let prompt;
  if (arrived) prompt = <span style={{ color: "#e3a542", fontWeight: 700 }}>{journeyEnd}. All {pool.length}.</span>;
  else if (typing) prompt = <span style={{ color: "#8b93a7" }}>Name the marked {noun}</span>;
  else
    prompt = (
      <>
        Find <span style={{ color: "#e3a542", fontWeight: 700 }}>{target.n}</span>
      </>
    );

  const showLabels = (k) => k >= 2.5;

  return (
    <div className="icq-layout">
      <TapMap gestures={gestures} label={arrived ? `Map of India, every ${noun} found.` : "Map of India."}>
        {(k) => (
          <>
            <BaseMap dim="#39445a" k={k} elevation={elevation} />

            {/* Places already reached stay on the map for the rest of the run —
                as filled shapes in the states game, as dots in the cities one,
                matching how each is marked when you answer it. */}
            {journey &&
              [...solved].map((id) => {
                const c = pool.find((x) => x.id === id);
                if (!c || (target && c.id === target.id)) return null;
                if (domain === "states") {
                  return (
                    STATE_PATH_BY_ID[c.id] && (
                      <g key={id} opacity={0.8}>
                        <path
                          d={STATE_PATH_BY_ID[c.id]}
                          fillRule="evenodd"
                          fill="#e3a542"
                          fillOpacity={0.26}
                          stroke="#e3a542"
                          strokeWidth={1.2 / k}
                          strokeLinejoin="round"
                        />
                        {STATE_SMALL.has(c.id) && (
                          <circle
                            cx={c.x}
                            cy={c.y}
                            r={13 / k}
                            fill="none"
                            stroke="#e3a542"
                            strokeWidth={1.4 / k}
                            opacity={0.8}
                          />
                        )}
                      </g>
                    )
                  );
                }
                return (
                  <g key={id}>
                    <circle cx={c.x} cy={c.y} r={3.4 / k} fill="#e3a542" />
                    {showLabels(k) && (
                      <text
                        x={c.x + 6 / k}
                        y={c.y + 3 / k}
                        fill="#e3a542"
                        fontSize={9 / k}
                        fontFamily="ui-monospace, Menlo, monospace"
                        opacity={0.85}
                      >
                        {c.n}
                      </text>
                    )}
                  </g>
                );
              })}

            {/* The just-answered target stays marked until the next answer
                replaces it — same lifetime as the card in the side panel, so
                the map and the text never disagree about which guess they're
                describing. State-mode guesses highlight the actual shape
                instead of a point: there's no single "correct spot" inside a
                state the way there is for a city, so a dot only ever points
                at an arbitrary spot rather than the answer — the shape itself,
                colored by whether you got it right, is the answer. Get it
                wrong and two shapes light up: the one you picked in red, the
                one you were after in green, so the miss is legible as a pair. */}
            {lastAnswer &&
              (domain === "states" ? (
                <g key={lastAnswer.key}>
                  {!lastAnswer.correct &&
                    lastAnswer.guessId &&
                    lastAnswer.guessId !== lastAnswer.id && (
                      <StateHighlight id={lastAnswer.guessId} color="#e2645a" k={k} />
                    )}
                  <StateHighlight id={lastAnswer.id} color="#5fbf7a" k={k} />
                </g>
              ) : (
                <g key={lastAnswer.key} opacity={0.65}>
                  {lastAnswer.atX !== undefined && (
                    <line
                      x1={lastAnswer.atX}
                      y1={lastAnswer.atY}
                      x2={lastAnswer.tx}
                      y2={lastAnswer.ty}
                      stroke={lastAnswer.correct ? "#5fbf7a" : "#e2645a"}
                      strokeWidth={1.2 / k}
                      strokeDasharray={`${3 / k} ${3 / k}`}
                      opacity={0.8}
                    />
                  )}
                  <circle
                    cx={lastAnswer.tx}
                    cy={lastAnswer.ty}
                    r={11 / k}
                    fill="none"
                    stroke="#5fbf7a"
                    strokeWidth={2 / k}
                  />
                  <circle cx={lastAnswer.tx} cy={lastAnswer.ty} r={4 / k} fill="#5fbf7a" />
                  {lastAnswer.atX !== undefined && (
                    <circle
                      cx={lastAnswer.atX}
                      cy={lastAnswer.atY}
                      r={5 / k}
                      fill={lastAnswer.correct ? "#5fbf7a" : "#e2645a"}
                      stroke="#0c1219"
                      strokeWidth={1.6 / k}
                    />
                  )}
                </g>
              ))}

            {/* Name it: the dot is the question. */}
            {typing && target && (
              <g>
                <circle
                  className="icq-ping"
                  cx={target.x}
                  cy={target.y}
                  r={13 / k}
                  fill="none"
                  stroke={TARGET_FILL}
                  strokeWidth={2 / k}
                />
                <circle cx={target.x} cy={target.y} r={4.2 / k} fill={TARGET_FILL} />
                <circle cx={target.x} cy={target.y} r={9 / k} fill="none" stroke={TARGET_FILL} strokeWidth={1.4 / k} opacity={0.7} />
              </g>
            )}

            <Borders on={borders} k={k} />
          </>
        )}
      </TapMap>

      <div className="icq-side">
        {journey ? (
          <Progress count={count} total={pool.length} km={Math.round(frac * TOTAL_KM)} frac={frac} score={score} legs={legs} />
        ) : (
          <ScoreRow score={score} />
        )}

        <div style={S.prompt}>{prompt}</div>
        <div style={S.subPrompt}>
          {arrived
            ? "\u00a0"
            : hints
            ? domain === "states"
              ? target.role
              : `${target.role} · ${target.country}`
            : "\u00a0"}
        </div>

        {arrived ? (
          <div style={S.row}>
            <div style={{ ...S.feedback, flex: 1, color: "#e3a542" }}>
              {score.total} guesses from {journeyStart}.
            </div>
            <button className="icq-btn" style={S.primary} onClick={restart}>
              Ride again
            </button>
          </div>
        ) : typing ? (
          <div style={S.row}>
            <input
              ref={inputRef}
              className="icq-input"
              type="text"
              name="city-answer"
              autoComplete="off"
              data-1p-ignore
              data-lpignore="true"
              data-bwignore
              data-form-type="other"
              style={{
                ...S.input,
                borderColor: lastAnswer ? (lastAnswer.correct ? "#5fbf7a" : "#e2645a") : "#2a3241",
              }}
              placeholder={`Name the marked ${noun}`}
              value={typed}
              autoCapitalize="words"
              autoCorrect="off"
              onChange={(e) => setTyped(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") submitTyped();
              }}
            />
            <button className="icq-btn" style={S.primary} onClick={submitTyped}>
              Check
            </button>
          </div>
        ) : (
          target &&
          domain === "states" &&
          smallShapes.has(target.id) && (
            <div style={{ ...S.hint, textAlign: "left" }}>
              This one's small on the map — zoom in before you commit.
            </div>
          )
        )}

        <LastAnswerCard last={lastAnswer} />
      </div>
    </div>
  );
}

// The persistent record of the last guess: what it was, whether it landed,
// and a fact or two about the place either way. Stays put until overwritten.
function LastAnswerCard({ last }) {
  if (!last) {
    return (
      <div style={S.card}>
        <div style={S.cardPlaceholder}>Your last guess will show up here.</div>
      </div>
    );
  }
  const color = last.correct ? "#5fbf7a" : "#e2645a";
  return (
    <div style={{ ...S.card, borderLeftColor: color }}>
      <div style={S.cardTop}>
        <span style={S.cardName}>{last.n}</span>
        <span style={{ ...S.cardVerdict, color }}>{last.correct ? "Correct" : "Missed"}</span>
      </div>
      <div style={S.cardMeta}>
        {last.domain === "states" ? (
          <>{last.role} · capital {last.capital} · pop. {last.pop}</>
        ) : (
          <>{last.role} of {last.country} · pop. {last.pop}</>
        )}
      </div>
      {last.guessText !== undefined && !last.correct && (
        <div style={S.cardGuess}>You wrote “{last.guessText}.”</div>
      )}
      <div style={S.cardBlurb}>{last.b}</div>
    </div>
  );
}

function SegButton({ label, active, onClick }) {
  return (
    <button
      className="icq-btn"
      onClick={onClick}
      style={{
        ...S.segBtn,
        background: active ? "#2a3241" : "transparent",
        color: active ? "#f3e9d8" : "#8b93a7",
      }}
    >
      {label}
    </button>
  );
}

function Progress({ count, total, km, frac, score, legs }) {
  return (
    <div>
      <div style={S.scoreRow}>
        <span style={S.scoreMain}>
          {km.toLocaleString()} km
          <span style={{ color: "#8b93a7", fontSize: 12 }}> / {TOTAL_KM.toLocaleString()}</span>
        </span>
        <span style={S.scoreMuted}>
          {count}/{total} · {score.total} guesses
        </span>
      </div>
      <div style={S.trackOuter}>
        <div style={{ ...S.trackFill, width: `${frac * 100}%` }} />
        {legs.slice(1, -1).map((l, i) => (
          <div key={l.name + i} style={{ ...S.tick, left: `${l.at * 100}%` }} />
        ))}
      </div>
      <div style={S.campLabel}>{legFor(frac, legs)}</div>
    </div>
  );
}

function ScoreRow({ score }) {
  const pct = score.total ? Math.round((score.correct / score.total) * 100) : 0;
  return (
    <div style={S.scoreRow}>
      <span style={S.scoreMain}>
        {score.correct}/{score.total}
      </span>
      <span style={S.scoreMuted}>{score.total ? pct + "%" : "—"}</span>
    </div>
  );
}

function Compass() {
  return (
    <svg width={30} height={30} viewBox="0 0 34 34" style={S.compass} aria-hidden="true">
      <circle cx="17" cy="17" r="14" fill="none" stroke="#5a6579" strokeWidth="1" />
      <path d="M17 5 L20 17 L17 29 L14 17 Z" fill="#5a6579" />
      <circle cx="17" cy="17" r="2" fill="#0c1219" />
    </svg>
  );
}

